import os
from typing import Callable, Optional

import boto3


class StreamingSpeechToText:
    def __init__(
        self,
        language_code: str = "en-US",
        sample_rate_hz: int = 16000,
        media_encoding: str = "pcm",
        region_name: Optional[str] = None,
    ):
        self.language_code = language_code
        self.sample_rate_hz = sample_rate_hz
        self.media_encoding = media_encoding
        self.client = boto3.client("transcribe", region_name=region_name or os.getenv("AWS_REGION"))

    def transcribe_stream(
        self,
        audio_stream,
        on_partial: Optional[Callable[[str], None]] = None,
        on_final: Optional[Callable[[str], None]] = None,
    ):
        """
        audio_stream: an iterable yielding raw PCM bytes chunks.
        on_partial: called with interim transcription text.
        on_final: called with finalized transcription text.
        """
        stream = self.client.start_stream_transcription(
            LanguageCode=self.language_code,
            MediaSampleRateHertz=self.sample_rate_hz,
            MediaEncoding=self.media_encoding,
            AudioStream=audio_stream,
        )

        for event in stream["TranscriptResultStream"]:
            transcript_event = event.get("TranscriptEvent")
            if not transcript_event:
                continue

            results = transcript_event.get("Transcript", {}).get("Results", [])
            for result in results:
                alternatives = result.get("Alternatives", [])
                if not alternatives:
                    continue

                transcript_text = alternatives[0].get("Transcript", "")
                if not transcript_text:
                    continue

                if result.get("IsPartial", False):
                    if on_partial:
                        on_partial(transcript_text)
                else:
                    if on_final:
                        on_final(transcript_text)
